L11_1 = {}
L11_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE1@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 6800106
L11_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_Talk_KOREA = "어떤 갈등이 벌어지던 클라이맥스에 이르러 빛과 함께 나타나 모든 갈등을 해결하는 사람."
L11_1.m_fTalkTime = 0.03
L11_1.m_bTalkCenterFadeIn = true
L11_1.m_Talk_JPN = "どんな争いが起こってもクライマックスには光とともに現れ、すべてを解決してくれる人。"
L11_1.m_Talk_ENG = "He would appear with light during the climax of any conflict and resolve it."
L11_1.m_Talk_TWN = "不管發生怎樣的危險，都會在危機關頭如超人一般登場，解決一切麻煩之人。"
L11_1.m_Talk_SCN = "不管发生怎样的危险，都会在危机关头如天外救星一般登场，解决一切麻烦之人。"
L11_1.m_Talk_DEU = "He would appear with light during the climax of any conflict and resolve it."
L11_1.m_Talk_FRA = "He would appear with light during the climax of any conflict and resolve it."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE1@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 6800106
L12_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Talk_KOREA = "그 자체만으로도 너무나 눈부셔서 마치 백조와 같았던 사람."
L12_1.m_fTalkTime = 0.03
L12_1.m_bTalkCenterFadeIn = true
L12_1.m_Talk_JPN = "存在自体があまりにも眩しくて、まるで白鳥のような人だった。"
L12_1.m_Talk_ENG = "A person who was so radiant and graceful like a swan."
L12_1.m_Talk_TWN = "他本身就如此耀眼，宛如一隻白天鵝。"
L12_1.m_Talk_SCN = "他本身就是如此得耀眼，宛如一只白天鹅般。"
L12_1.m_Talk_DEU = "A person who was so radiant and graceful like a swan."
L12_1.m_Talk_FRA = "A person who was so radiant and graceful like a swan."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE1@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 6800106
L13_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Talk_KOREA = "그리고 누구에게도 진정으로 이해 받지 못했던 날 인정해 주었던 유일한 사람."
L13_1.m_fTalkTime = 0.03
L13_1.m_bTalkCenterFadeIn = true
L13_1.m_Talk_JPN = "そして誰からも理解してもらえなかった私を認めてくれた、唯一の人。"
L13_1.m_Talk_ENG = "The only person who acknowledged me when I was misunderstood by everyone."
L13_1.m_Talk_TWN = "他是唯一一個真正理解並認可我的人。"
L13_1.m_Talk_SCN = "他是唯一一个真正理解并认可我的人。"
L13_1.m_Talk_DEU = "The only person who acknowledged me when I was misunderstood by everyone."
L13_1.m_Talk_FRA = "The only person who acknowledged me when I was misunderstood by everyone."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE1@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 6800106
L14_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Talk_KOREA = "<color=#ffd34c>그 남자</color>……."
L14_1.m_fTalkTime = 0.03
L14_1.m_bTalkCenterFadeIn = true
L14_1.m_Talk_JPN = "<color=#ffd34c>あの男</color>……"
L14_1.m_Talk_ENG = "<color=#ffd34c>The man</color>..."
L14_1.m_Talk_TWN = "<color=#ffd34c>那個男人</color>……"
L14_1.m_Talk_SCN = "<color=#ffd34c>那个男人</color>……"
L14_1.m_Talk_DEU = "<color=#ffd34c>The man</color>..."
L14_1.m_Talk_FRA = "<color=#ffd34c>The man</color>..."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE1@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 6800106
L15_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_Talk_KOREA = "나의 세계는 이미 내일을 빼앗겨 버렸고, 그 남자 역시 더는 존재하지 않지만."
L15_1.m_fTalkTime = 0.03
L15_1.m_bTalkCenterFadeIn = true
L15_1.m_Talk_JPN = "私の世界はすでに明日を奪われてしまった。あの男もまた存在しない。"
L15_1.m_Talk_ENG = "The future of my world has already been robbed, and he no longer exists."
L15_1.m_Talk_TWN = "我的世界已經失去了明天，那個人也不再存在了。"
L15_1.m_Talk_SCN = "我的世界已经失去了明天，那个人也不再存在了。"
L15_1.m_Talk_DEU = "The future of my world has already been robbed, and he no longer exists."
L15_1.m_Talk_FRA = "The future of my world has already been robbed, and he no longer exists."
L16_1 = {}
L16_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE1@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 6800106
L16_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Talk_KOREA = "그럼에도 나는 여전히 그 남자와 함께 했던 사건을 떠올리곤 한다."
L16_1.m_fTalkTime = 0.03
L16_1.m_bTalkCenterFadeIn = true
L16_1.m_Talk_JPN = "それでも私は、今でもあの男との事件を思い出す。"
L16_1.m_Talk_ENG = "Yet, I still reminisce about the incident I had with the man."
L16_1.m_Talk_TWN = "儘管如此，我仍會時常回想起和那個男人一起經歷的一切。"
L16_1.m_Talk_SCN = "尽管如此，我仍会时常回想起和那个男人一起经历的一切。"
L16_1.m_Talk_DEU = "Yet, I still reminisce about the incident I had with the man."
L16_1.m_Talk_FRA = "Yet, I still reminisce about the incident I had with the man."
