L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_Talk_KOREA = "그 각본의 끝에 어떤 결말이 기다리고 있다 하더라도."
L22_1.m_fTalkTime = 0.03
L22_1.m_bTalkCenterFadeIn = true
