L22_1.m_Talk_ENG = "No matter what ending awaits me at the end of it."
L22_1.m_Talk_TWN = "即使在那個劇本的結尾，等待我的是某種結局。"
L22_1.m_Talk_SCN = "无论在那个剧本的结尾等待着我的会是怎样的结局。"
