L48_1 = {}
L48_1.m_CutScenKey_Talk = "SWANSONG_ACT1_INTERLUDE1@48#Talk"
L48_1.m_CutScenProcessKey = 48
L48_1.m_CutScenID = 6800106
L48_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_CharStrID = "RIPPER_SWANSONG_NPC_QM"
L48_1.m_Pos = "C"
L48_1.m_Talk_KOREA = "그건 이 세계가 너무나 타락했기 때문이야. 그래서 제물이 필요한 거지."
L48_1.m_fTalkTime = 0.03
L48_1.m_Talk_JPN = "それはこの世界があまりにも堕落しすぎたからだよ。だから生贄が必要なんだ。"
L48_1.m_Talk_ENG = "That's because the world has lost its grace. And we need to offer a sacrifice."
L48_1.m_Talk_TWN = "那是因為這個世界已經墮落得太深了，所以才需要祭品。"
L48_1.m_Talk_SCN = "那是因为这个世界已经堕落得太深了。所以才需要祭品。"
L48_1.m_Talk_DEU = "That's because the world has lost its grace. And we need to offer a sacrifice."
L48_1.m_Talk_FRA = "That's because the world has lost its grace. And we need to offer a sacrifice."
L49_1 = {}
