L49_1.m_CharStrID = "RIPPER_SWANSONG_NPC_QM"
L49_1.m_Pos = "C"
L49_1.m_Talk_KOREA = "이 부정한 세계에 종언을 고하고, 모든 것을 처음으로 되돌릴 수 있는……."
L49_1.m_fTalkTime = 0.03
L50_1 = "この不浄なる世界に終焉を告げ、すべてを最初へと戻すことができる……"
L49_1.m_Talk_JPN = L50_1
L50_1 = "To put an end to this unholy world, and revert everything to the beginning..."
