L13_1.m_CharStrID = L14_1
L14_1 = "서부전선은 마석을 사용한 신형 병기로 순조롭게 승리하고 있대요! 대영제국 만세!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "西部戦線は魔石を使った新型兵器で順調に勝利へと近づいているようです！　大英帝国万歳！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "The western front is winning smoothly with a new weapon that uses Mana Stones! Long live the British Empire!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "西部戰線投入使用魔石的新型兵器後順利取勝！大英帝國萬歲！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "西部战线投入使用魔石的新型兵器后顺利取胜！帝国万岁！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "The western front is winning smoothly with a new weapon that uses Mana Stones! Long live the British Empire!"
L13_1.m_Talk_DEU = L14_1
