L14_1.m_CharStrID = L15_1
L15_1 = "하지만 전쟁으로 마석 가격이 또 올랐대요! 아저씨들 임금은 또 떨어지겠네요!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "でも戦争でまた魔石が値上がりしたんですよ！　おじさんたちの賃金はまた下がりますね！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "The war has caused the price of Mana Stones to rise again! Guess your wages are going to get cut again!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "但別高興得太早，因為戰爭魔石的價格漲了又漲！大家的工資又要少了！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "但别高兴得太早，因为战争魔石的价格涨了又涨！大伙儿的工资又要少了！"
