L8_1 = "공연이라는 건 눈으로 보고, 귀로 듣지만, 결국에는 마음으로 느끼는 거니까."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "オペラは目で見て、耳で聞くけど、結局は心で感じるものだから。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Performances might all be about what you see and hear, but ultimately, it's about what you feel in your heart."
