L24_1 = "SWANSONG_ACT1_INTERLUDE1@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 6800106
L23_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "AUDIENCE_SWANSONG_NPC_M"
L23_1.m_CharStrID = L24_1
L24_1 = "같은 극이라고 해도, 무대 위에서 누가 배역을 맡느냐에 따라 다른 느낌을 주는군요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "同じ演劇でも、誰が演じるかによって、また違ってくるものですね。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Even if it's the same play, however, the entire atmosphere seems to change depending on who plays which role."
L23_1.m_Talk_ENG = L24_1
L24_1 = "即使是同一部劇，根據舞台上不同演員的演繹，也會帶來不同的感覺。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "即使是同一部剧，根据舞台上不同演员的演绎，也会带来不同的感觉。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Even if it's the same play, however, the entire atmosphere seems to change depending on who plays which role."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Even if it's the same play, however, the entire atmosphere seems to change depending on who plays which role."
L23_1.m_Talk_FRA = L24_1
