L25_1 = "SWANSONG_ACT1_INTERLUDE1@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 6800106
