L26_1 = "SWANSONG_ACT1_INTERLUDE1@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 6800106
L25_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "AUDIENCE_SWANSONG_NPC_M"
L25_1.m_CharStrID = L26_1
L26_1 = "특히 주인공 비올레타 역이 단연 인상 깊네요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "特に主人公のヴィオレッタ役が断然印象に残ります。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "I was especially impressed by the one who played the main character Violetta."
L25_1.m_Talk_ENG = L26_1
L26_1 = "特別是飾演主角薇奧麗塔的演員，真是令人印象深刻。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "特别是饰演主角薇奥莱塔的演员，真是令人印象深刻。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "I was especially impressed by the one who played the main character Violetta."
L25_1.m_Talk_DEU = L26_1
L26_1 = "I was especially impressed by the one who played the main character Violetta."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "SWANSONG_ACT1_INTERLUDE1@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 6800106
L26_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
