L26_1.m_fWaitTime = 0
L27_1 = "AUDIENCE_SWANSONG_NPC_F"
L26_1.m_CharStrID = L27_1
L27_1 = "후후, 이 극장은 처음이실 텐데 역시 안목이 높으시네요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ふふ、この劇場は初めてだと聞きましたが、さすがですわね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Haha, it should be your first time in this theater, but you have a keen eye, sir."
L26_1.m_Talk_ENG = L27_1
L27_1 = "呵呵，你應該是第一次來這個劇院吧，但果然眼光精準呢。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "呵呵，您应该是第一次来这个剧院吧，但果然眼光老辣呢。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Haha, it should be your first time in this theater, but you have a keen eye, sir."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Haha, it should be your first time in this theater, but you have a keen eye, sir."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "SWANSONG_ACT1_INTERLUDE1@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 6800106
L27_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
