L28_1 = "AUDIENCE_SWANSONG_NPC_F"
L27_1.m_CharStrID = L28_1
L28_1 = "프리마돈나를 맡고 있는 스완이라는 아이랍니다. 런던에서 가장 인기 있는 배우죠."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "プリマドンナを務めているのはスワンという子です。ロンドンでもっとも人気のある女優ですわ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "The prima donna was played by a child named Swan. She is the most popular actress in all of London right now."
L27_1.m_Talk_ENG = L28_1
L28_1 = "那是擔任首席女演員的史旺，是倫敦最受歡迎的演員。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "那是担任首席女演员的斯旺，是伦敦最受欢迎的演员。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "The prima donna was played by a child named Swan. She is the most popular actress in all of London right now."
L27_1.m_Talk_DEU = L28_1
L28_1 = "The prima donna was played by a child named Swan. She is the most popular actress in all of London right now."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "SWANSONG_ACT1_INTERLUDE1@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 6800106
L28_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
