L28_1.m_fWaitTime = 0
L29_1 = "AUDIENCE_SWANSONG_NPC_M"
L28_1.m_CharStrID = L29_1
L29_1 = "프리마돈나? 저렇게 어린 나이인데요?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "あんな幼い子がプリマドンナですか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Prima donna? But she's so young."
L28_1.m_Talk_ENG = L29_1
L29_1 = "歌劇女主角？她還那麼年輕呢？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "歌剧女主角？她还那么年轻呢？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Prima donna? But she's so young."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Prima donna? But she's so young."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "SWANSONG_ACT1_INTERLUDE1@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 6800106
L29_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "AUDIENCE_SWANSONG_NPC_F"
L29_1.m_CharStrID = L30_1
L30_1 = "저 아이를 한마디로 표현하자면 <color=#ffd34c>백조</color>라고 할 수 있겠네요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "あの子を一言で表すなら……<color=#ffd34c>白鳥</color>と言えるかしら。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Much like her name, I would describe her as a graceful <color=#ffd34c>swan</color>."
L29_1.m_Talk_ENG = L30_1
L30_1 = "如果要用一個詞來形容那個孩子的話，那就是<color=#ffd34c>天鵝</color>吧。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "如果要用一个词来形容那个孩子的话，那就是<color=#ffd34c>天鹅</color>吧。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Much like her name, I would describe her as a graceful <color=#ffd34c>swan</color>."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Much like her name, I would describe her as a graceful <color=#ffd34c>swan</color>."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "SWANSONG_ACT1_INTERLUDE1@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 6800106
L30_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "AUDIENCE_SWANSONG_NPC_F"
L30_1.m_CharStrID = L31_1
L31_1 = "한 번 읽은 대본과 노래는 그 자리에서 외워버리는 건 기본이고."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "一度目を通した台本と歌はその場ですべて暗記してしまうとか。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "She can memorize the script and songs after reading them once."
L30_1.m_Talk_ENG = L31_1
L31_1 = "讀過一次的劇本和歌曲，當場背下來便是最基本的。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "读过一次的剧本和歌曲，当场背下来便是最基本的。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "She can memorize the script and songs after reading them once."
L30_1.m_Talk_DEU = L31_1
L31_1 = "She can memorize the script and songs after reading them once."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "SWANSONG_ACT1_INTERLUDE1@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 6800106
L31_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "AUDIENCE_SWANSONG_NPC_F"
L31_1.m_CharStrID = L32_1
L32_1 = "콘트랄토부터 소프라노까지. 거의 모든 배역을 소화할 수 있는 음역대를 타고났으니까요."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "それにコントラルトからソプラノまで、ほぼすべての役を演じられる声を持ってるそうよ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "And has the vocal range to cover any and all roles from contralto to soprano."
L31_1.m_Talk_ENG = L32_1
L32_1 = "更別說從女低音到女高音，她天生就擁有幾乎能勝任所有角色的音域。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "更别说从女低音到女高音，她天生就拥有几乎能胜任所有角色的音域。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "And has the vocal range to cover any and all roles from contralto to soprano."
L31_1.m_Talk_DEU = L32_1
L32_1 = "And has the vocal range to cover any and all roles from contralto to soprano."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
