L33_1 = "AUDIENCE_SWANSONG_NPC_F"
L32_1.m_CharStrID = L33_1
L33_1 = "수준 높은 이곳 오페라 하우스에서도 저 아이의 재능은 단연 최고랍니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "全体的にレベルの高いこのオペラハウスでも、あの子の才能は並外れたものですわ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Even in this opera house with so many talents, her talent is, by far, the best."
L32_1.m_Talk_ENG = L33_1
L33_1 = "即使在這個高水準的歌劇院，她的才華也是無可爭議的頂尖。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "即使在这个高水平的歌剧院，她的才华也是无可争议的顶尖。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Even in this opera house with so many talents, her talent is, by far, the best."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Even in this opera house with so many talents, her talent is, by far, the best."
