L46_1.m_CharStrID = L47_1
L47_1 = "L"
L46_1.m_Pos = L47_1
L47_1 = "고생 많았어, 스완. 오늘 무대도 반응이 아주 뜨겁던데?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "お疲れ様、スワン。今日の舞台もすごい盛り上がりだったわね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Great work, Swan. The audience's reactions were so enthusiastic."
L46_1.m_Talk_ENG = L47_1
L47_1 = "辛苦了，史旺。今天的舞台反應也很熱烈吧？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "辛苦了，斯旺。今天的舞台反响也很热烈吧？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Great work, Swan. The audience's reactions were so enthusiastic."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Great work, Swan. The audience's reactions were so enthusiastic."
L46_1.m_Talk_FRA = L47_1
