L47_1.m_CharStrID = L48_1
L48_1 = "L"
L47_1.m_Pos = L48_1
L48_1 = "네가 프리마돈나가 된 뒤로 극장 매출이 세 배 가까이 올랐지 뭐야?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "あなたがプリマドンナになってから、劇場の売り上げが三倍近く跳ね上がったのよ！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Did you know that theater sales have nearly tripled since you became a prima donna?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "自從你成為首席女演員後，劇院的收入幾乎翻了三倍呢。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "自从你成为首席女演员后，剧院的收入几乎翻了三倍呢。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Did you know that theater sales have nearly tripled since you became a prima donna?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Did you know that theater sales have nearly tripled since you became a prima donna?"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "SWANSONG_ACT1_INTERLUDE1@148#Talk"
