L50_1 = "R"
L49_1.m_Pos = L50_1
L50_1 = "후우, 관객분들께서 좋아해 주셔서 다행이야. 메리 제인."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ふう、お客さんが気に入ってくれてなによりだわ。メリー・ジェーン。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "*Sigh* I'm relieved to hear that our audience liked it, Mary Jane."
L49_1.m_Talk_ENG = L50_1
L50_1 = "呼——，觀眾們喜歡就好。瑪麗·珍。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "呼——，观众们喜欢就好。玛丽·简。"
