L2_1 = "후후, 또 마음에도 없는 소리네. 이젠 안 속는다구?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "ふふ、またそんな謙遜して。もう騙されないからね？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Haha. Stop trying to be so modest. I'm not falling for that again."
L1_1.m_Talk_ENG = L2_1
L2_1 = "呵呵，又在說客套話了。我現在可不會再上當了喔？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "呵呵，又在说违心的话了。我现在可不会再上当了哦？"
