L3_1 = "저기 쌓여 있는 팬레터만 다 모아도 어지간한 위인전보다 분량이 많을걸?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "そこの山積みになってるファンレターをまとめたら、よくある偉人伝より分厚い本ができるよ？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Just seeing your pile of fan letters could make a book thicker than any famous person's autobiography."
L2_1.m_Talk_ENG = L3_1
L3_1 = "那邊堆積的粉絲信，光是全部收集起來，分量就比一般的偉人傳記還多吧？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "那边堆积的粉丝信，光是全部收集起来，分量就比一般的伟人传记还多吧？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Just seeing your pile of fan letters could make a book thicker than any famous person's autobiography."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Just seeing your pile of fan letters could make a book thicker than any famous person's autobiography."
