L4_1 = "하아, 모든 런던 시민에게 사랑받는 삶이라니. 부럽다, 부러워."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "はあ、ロンドンの全市民に愛される人生って、羨ましいなあ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "*Sigh* I'm so jealous of you. I want to know what it feels like to be loved by everyone in London."
L3_1.m_Talk_ENG = L4_1
L4_1 = "哎，能過上被所有倫敦市民喜愛的生活，真讓人羡慕啊。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "哎，能过上被所有伦敦市民喜爱的生活。真让人羡慕啊。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "*Sigh* I'm so jealous of you. I want to know what it feels like to be loved by everyone in London."
L3_1.m_Talk_DEU = L4_1
