L5_1 = "나도 너처럼 예쁘고 재능 있었다면, 무대 뒤가 아니라 당당히 앞에 설 수 있을 텐데."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "私もあなたみたいに可愛くて、才能があったら、舞台裏じゃなくて堂々と表に立つことができたのに。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "If I were as pretty and talented as you, I think I could also confidently go up on stage instead of being behind it."
L4_1.m_Talk_ENG = L5_1
L5_1 = "如果我也像你一樣漂亮又有才華，就能堂堂正正地站在舞台前，而不是躲在幕後了。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "如果我也像你一样漂亮又有才华，就能堂堂正正地站在舞台前，而不是躲在幕后了。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "If I were as pretty and talented as you, I think I could also confidently go up on stage instead of being behind it."
