L9_1 = "배우가 빛날 수 있는 건, 무대 뒤편에서 스태프가 스포트라이트를 비춰주기 때문이야."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "役者が輝いて見えるのは、舞台裏でスタッフがスポットライトを照らしてくれるからだよ。"
L8_1.m_Talk_JPN = L9_1
