L10_1 = "배우와 스태프. 모든 것이 조화로워야 비로소 훌륭한 무대를 보여줄 수 있거든."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "役者とスタッフのつり合いがとれてこそ、素敵な舞台が出来上がるの。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Actors and staff must work in harmony to give an outstanding performance."
L9_1.m_Talk_ENG = L10_1
L10_1 = "演員和幕後。只有所有人都和諧相處，才能呈現出精彩的舞台。"
