L10_1[L11_1] = 0.01
L11_1 = "팬들이 보내주는 성원은 나 한 사람이 아닌, 무대 그리고 우리 극단 전체를 향하는 거야."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ファンが送ってくれる声援は私にだけじゃなくて、舞台と劇団全体に向けられているのよ。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "The love from fans isn't directed at one person like me, but our entire theater and troupe."
L10_1.m_Talk_ENG = L11_1
L11_1 = "粉絲們的支持不僅是給我一個人的，而是給整個舞台和我們的劇團。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "粉丝们的支持不仅是给我一个人的，而是给整个舞台和我们的剧团。"
