L13_1 = "아니, 자부심을 느껴도 돼. 메리 제인에겐 그럴 자격이 있는 걸?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "むしろ、誇りに思ってほしい。メリー・ジェーンにはその資格があるもの。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "No, you're allowed to be proud. You deserve it, Mary Jane."
L12_1.m_Talk_ENG = L13_1
L13_1 = "不，你應該感到自豪。瑪麗·珍是值得擁有這種資格的！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "不，你应该感到自豪。玛丽·简是值得拥有这种资格的！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "No, you're allowed to be proud. You deserve it, Mary Jane."
L12_1.m_Talk_DEU = L13_1
L13_1 = "No, you're allowed to be proud. You deserve it, Mary Jane."
L12_1.m_Talk_FRA = L13_1
