L14_1 = "나도 극단을 대표하는 배우로서, 언제나 당당히 무대에 설 테니까."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "私も劇団を代表する役者として、いつだって堂々と舞台に立つから。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "As the actress who represents our theater company, I'll also stay confident on stage."
L13_1.m_Talk_ENG = L14_1
L14_1 = "而作為劇團的首席演員，我也會一直自信地站在舞台上！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "而作为剧团的首席演员，我也会一直自信地站在舞台上！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "As the actress who represents our theater company, I'll also stay confident on stage."
L13_1.m_Talk_DEU = L14_1
L14_1 = "As the actress who represents our theater company, I'll also stay confident on stage."
L13_1.m_Talk_FRA = L14_1
