L14_1.m_Pos = "C"
L15_1 = "하아, 스완은 무대 이야기만 나오면 눈빛이 진지해진다니까."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "はあ、スワンって舞台の話になると目つきが変わるんだよね。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "*Sigh* Your eyes always get serious when you start talking about the stage, Swan."
L14_1.m_Talk_ENG = L15_1
L15_1 = "唉，一提到舞台，你的眼神就會變得認真起來。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "唉，一提到舞台，你的眼神就会变得认真起来。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "*Sigh* Your eyes always get serious when you start talking about the stage, Swan."
L14_1.m_Talk_DEU = L15_1
