L16_1 = "그래도 런던 최고의 프리마돈나에게 칭찬받으니, 기분이 나쁘진 않은데?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "でもロンドンで一番人気のプリマドンナに褒められるって、気分がいいね。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "But it's nice to hear a compliment from London's best prima donna."
L15_1.m_Talk_ENG = L16_1
L16_1 = "不過被倫敦最棒的女主角誇獎，心情還不錯呢？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "不过被伦敦最棒的女主角夸奖，心情还不错呢？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "But it's nice to hear a compliment from London's best prima donna."
L15_1.m_Talk_DEU = L16_1
L16_1 = "But it's nice to hear a compliment from London's best prima donna."
