L26_1 = "오늘도 왔답니다. 이름 모를 열렬한 팬께서 보낸 팬레터가요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "今日も届きましたよ。匿名の熱狂的なファンからのファンレター。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Here's another one. It's a fan letter from an anonymous fan."
