L30_1 = "POSTMAN_SWANSONG_NPC_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "글쎄요. 신사 분께서는 매번 자기 이름을 적지 않고 보내시니까요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "さあ、この方は毎回差出人の名前を書かずに出していますから。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Well. The gentleman always sends it without writing down his name."
L29_1.m_Talk_ENG = L30_1
L30_1 = "這個嘛，那位先生每次都不寫自己的名字就寄過來了。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "这个嘛。那位先生每次都不写自己的名字就寄过来了。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Well. The gentleman always sends it without writing down his name."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Well. The gentleman always sends it without writing down his name."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "SWANSONG_ACT1_INTERLUDE1@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 6800106
L30_1.m_CutScenStrID = "SWANSONG_ACT1_INTERLUDE1"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "POSTMAN_SWANSONG_NPC_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "저희 왕립 우정국은 최고의 서비스를 위해, <color=#ffd34c>왕실 우표</color>가 붙은 우편은 반드시 수신인에게 직접 전달해 드리는 게 원칙이라서요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "我々王立郵政局は最高のサービスを提供するために、原則として<color=#ffd34c>王室の切手</color>が貼られた郵便物は必ず受取人に直接届けるようにしています。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "And for us, the Royal Post Office, to provide the best service, it's our policy to deliver letters with the <color=#ffd34c>royal stamp</color> directly to the recipient."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我們皇家郵局為了提供最優質的服務，只要是貼上了<color=#ffd34c>皇家郵票</color>的郵件，無論如何都必須送到收件人手中，這是我們的原則。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "我们皇家邮政局为了提供最优质的服务，只要是贴上了<color=#ffd34c>皇家邮票</color>的邮件，无论如何都必须送到收件人手中，这是我们的原则。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "And for us, the Royal Post Office, to provide the best service, it's our policy to deliver letters with the <color=#ffd34c>royal stamp</color> directly to the recipient."
L30_1.m_Talk_DEU = L31_1
L31_1 = "And for us, the Royal Post Office, to provide the best service, it's our policy to deliver letters with the <color=#ffd34c>royal stamp</color> directly to the recipient."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
