L3_1 = "その代わり、何か危険を感じたら必ず正直に話してよね。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Instead, promise me that you'll tell me the truth if anything dangerous happens, okay?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "但是如果發生了什麼危險的事情，一定要告訴我，好嗎？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "但是如果发生了什么危险的事情，一定要告诉我真相，好吗？"
